  function open(){setup();$("#adminLayer").classList.remove("hidden");$("#adminLogin").classList.remove("hidden");$("#adminContent").classList.add("hidden");$("#adminPin").value="";$("#adminPin").focus();$("#pinHint").textContent=localStorage.getItem(PIN_KEY)?"أدخل رمز الإدارة.":"أول استخدام: اختر رمزًا جديدًا من 4 أرقام أو أكثر وسيتم حفظه على هذا الجهاز.";}
